// Parse trigger source and prepare workflow data for WEEKLY digest
const items = $input.all();
const firstItem = items[0];

let triggerType = 'schedule';
let webhookData = null;
let callbackData = null;

// Check if this came from webhook (has body)
if (firstItem && firstItem.json && firstItem.json.body) {
  webhookData = firstItem.json.body;

  // Check if it's a callback (has action and digest_id)
  if (webhookData.action && webhookData.digest_id) {
    triggerType = 'callback';
    callbackData = {
      action: webhookData.action,
      digest_id: webhookData.digest_id,
      callback_query_id: webhookData.callback_query_id,
      chat_id: webhookData.chat_id,
      message_id: webhookData.message_id,
      edited_content: webhookData.edited_content || null
    };
  } 
  // Otherwise it's a manual trigger
  else if (webhookData.trigger === 'manual') {
    triggerType = 'manual';
  }
}

// Get today's date in consistent format (YYYY-MM-DD)
const today = new Date();
const todayDate = today.toISOString().split('T')[0];

// Get date 7 days ago for weekly digest
const weekAgo = new Date(today);
weekAgo.setDate(weekAgo.getDate() - 7);
const weekAgoDate = weekAgo.toISOString().split('T')[0];

// Get week number for digest identification
const getWeekNumber = (d) => {
  d = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
};
const weekNumber = getWeekNumber(today);
const weekIdentifier = `${today.getFullYear()}-W${String(weekNumber).padStart(2, '0')}`;

// Get Telegram Chat ID
// Priority: webhook data > hardcoded
const telegramChatId = (webhookData && webhookData.chat_id) 
  ? webhookData.chat_id 
  : '1925139795';

// Prepare output
return {
  triggerType: triggerType,
  todayDate: todayDate,
  weekAgoDate: weekAgoDate,
  weekIdentifier: weekIdentifier,
  timestamp: new Date().toISOString(),
  webhookData: webhookData,
  callbackData: callbackData,
  telegramChatId: telegramChatId
};

// WEEKLY DIGEST: Score and select TOP 5-7 articles from the week
// Enhanced scoring algorithm for LinkedIn 2025 algorithm compliance
const items = $input.all();
const SITE_BASE_URL = 'https://cemkoyluoglu.codes/tech-news';

// Category weights optimized for tech audience engagement
const categoryWeights = {
  'AI': 1.5,           // AI content performs best on LinkedIn
  'Cybersecurity': 1.3,
  'Cloud': 1.2,
  'Hardware': 1.2,
  'Data Science': 1.15,
  'Software': 1.1,
  'General': 0.8
};

// Breaking news keywords that indicate high-impact stories
const breakingKeywords = [
  'breakthrough', 'first', 'launch', 'announce', 'release',
  'billion', 'million', 'acquisition', 'partnership', 'record',
  'new', 'major', 'revolutionary', 'game-changing'
];

// Trusted sources for higher credibility
const trustedSources = [
  'techcrunch.com', 'theverge.com', 'arstechnica.com', 'wired.com',
  'mit.edu', 'stanford.edu', 'reuters.com', 'bloomberg.com',
  'zdnet.com', 'cnet.com', 'engadget.com'
];

// Calculate enhanced score for each article
const articlesWithScores = items.map(item => {
  const articleUrl = `${SITE_BASE_URL}/${item.json.slug}`;

  const article = {
    id: item.json.id,
    title: item.json.title,
    title_en: item.json.title_en,
    summary_en: item.json.summary_en,
    slug: item.json.slug,
    category: item.json.category,
    article_url: articleUrl,
    created_at: item.json.created_at,
    date: item.json.date
  };

  let score = 0;
  const titleLower = (article.title_en || article.title || '').toLowerCase();
  const summaryLower = (article.summary_en || '').toLowerCase();

  // 1. Breaking News Score (0-40 points) - high-impact stories
  const breakingScore = breakingKeywords.reduce((acc, keyword) => {
    if (titleLower.includes(keyword)) return acc + 8;
    if (summaryLower.includes(keyword)) return acc + 4;
    return acc;
  }, 0);
  score += Math.min(40, breakingScore);

  // 2. Category Weight Score (0-30 points)
  const categoryWeight = categoryWeights[article.category] || 1.0;
  score += categoryWeight * 20;

  // 3. Source Credibility Score (0-25 points)
  const originalSourceUrl = item.json.source_url || item.json.original_source || '';
  const isTrustedSource = trustedSources.some(trusted => originalSourceUrl.includes(trusted));
  score += isTrustedSource ? 25 : 8;

  // 4. Content Quality Score (0-20 points)
  const summaryLength = (article.summary_en || '').length;
  const hasNumbers = /\d+/.test(article.title_en || '');
  const hasCompanyName = /[A-Z][a-z]+/.test(article.title_en || '');

  let qualityScore = 0;
  if (summaryLength > 100) qualityScore += 8;
  if (summaryLength > 200) qualityScore += 4;
  if (hasNumbers) qualityScore += 4;  // Numbers create curiosity
  if (hasCompanyName) qualityScore += 4;  // Company names increase relevance
  score += qualityScore;

  // 5. Recency Bonus (0-15 points) - prefer articles from last 3 days
  const articleDate = new Date(article.created_at);
  const now = new Date();
  const daysSincePublished = (now - articleDate) / (1000 * 60 * 60 * 24);
  const recencyScore = Math.max(0, 15 - (daysSincePublished * 2.5));
  score += recencyScore;

  return {
    ...article,
    _score: Math.round(score * 100) / 100,
    _scoreBreakdown: {
      breaking: Math.min(40, breakingScore),
      category: categoryWeight * 20,
      source: isTrustedSource ? 25 : 8,
      quality: qualityScore,
      recency: Math.round(recencyScore * 100) / 100
    }
  };
});

// Sort by score and select TOP 7 articles
const sortedArticles = articlesWithScores.sort((a, b) => b._score - a._score);
const topArticles = sortedArticles.slice(0, 7);

// Ensure category diversity - max 2 articles per category
const diverseArticles = [];
const categoryCounts = {};

for (const article of sortedArticles) {
  const cat = article.category || 'General';
  categoryCounts[cat] = (categoryCounts[cat] || 0);

  if (categoryCounts[cat] < 2) {
    diverseArticles.push(article);
    categoryCounts[cat]++;
  }

  if (diverseArticles.length >= 7) break;
}

// Use diverse selection if we have enough, otherwise use top scored
const finalArticles = diverseArticles.length >= 5 ? diverseArticles : topArticles;

// Clean output (keep scores for debugging in Telegram)
const articles = finalArticles.map(({ _scoreBreakdown, ...article }) => article);

return {
  articles: articles,
  articleCount: articles.length,
  totalArticlesThisWeek: items.length,
  weekIdentifier: $('Parse Trigger Type').item.json.weekIdentifier,
  dateRange: {
    from: $('Parse Trigger Type').item.json.weekAgoDate,
    to: $('Parse Trigger Type').item.json.todayDate
  },
  scoringInfo: {
    highestScore: sortedArticles[0]?._score || 0,
    lowestScore: sortedArticles[sortedArticles.length - 1]?._score || 0,
    averageScore: Math.round((sortedArticles.reduce((sum, a) => sum + a._score, 0) / sortedArticles.length) * 100) / 100,
    selectedCount: articles.length,
    categoryDistribution: categoryCounts
  }
};

// Prepare Telegram message with DUAL CONTENT (Group + Feed)
const digest = $input.first().json;
const dualContent = $('Generate Dual Content').first().json;

// Telegram has 4096 char limit per message
const MAX_MSG_LENGTH = 4000;

// Truncate helper
const truncate = (text, max) => {
  if (!text || text.length <= max) return text || '';
  return text.substring(0, max - 50) + '\n\n⚠️ [Truncated - see full in database]';
};

// === MESSAGE 1: GROUP CONTENT ===
const groupContent = dualContent.group_content || 'No group content generated';
const firstComment = dualContent.group_first_comment || '';

const groupMessage = `📢 *WEEKLY DIGEST - GROUP CONTENT*
━━━━━━━━━━━━━━━━━━━━━━━━
📅 Week: ${dualContent.weekIdentifier}
📊 Articles: ${dualContent.articleCount} selected from ${dualContent.totalArticlesThisWeek} total
━━━━━━━━━━━━━━━━━━━━━━━━

📝 *POST CONTENT (copy this):*

${truncate(groupContent, 2500)}

━━━━━━━━━━━━━━━━━━━━━━━━
💬 *FIRST COMMENT (paste after posting):*

${truncate(firstComment, 800)}

━━━━━━━━━━━━━━━━━━━━━━━━
📌 *Manual posting instructions:*
1. Copy the POST CONTENT above
2. Paste in LinkedIn Group
3. Post it
4. Immediately add FIRST COMMENT with links`;

// === MESSAGE 2: FEED CONTENT ===
const feedContent = dualContent.feed_content || 'No feed content generated';
const validation = dualContent.validation || {};

const feedMessage = `📰 *WEEKLY DIGEST - FEED CONTENT*
━━━━━━━━━━━━━━━━━━━━━━━━
📅 Week: ${dualContent.weekIdentifier}
📊 Status: ${validation.status || 'unknown'}
📏 Characters: ${validation.feed_chars || 0}/3000
━━━━━━━━━━━━━━━━━━━━━━━━

${truncate(feedContent, 2800)}

━━━━━━━━━━━━━━━━━━━━━━━━
✅ Choose an action for FEED post:`;

// Inline keyboard for feed approval
const replyMarkup = {
  inline_keyboard: [
    [
      { text: '✅ Approve & Post to Feed', callback_data: `approve_${digest.id}` },
      { text: '❌ Reject', callback_data: `reject_${digest.id}` }
    ],
    [
      { text: '✏️ Edit Feed Content', callback_data: `edit_${digest.id}` }
    ]
  ]
};

return {
  chatId: $('Parse Trigger Type').first().json.telegramChatId,
  groupMessage: groupMessage,
  feedMessage: feedMessage,
  replyMarkup: replyMarkup,
  digestId: digest.id,
  weekIdentifier: dualContent.weekIdentifier
};

