// Get the digest data from Fetch Digest by ID node
const digest = $('Fetch Digest by ID').first().json;

// Get edited_content if exists, otherwise use suggested_content (which is feed_content)
const content = digest.edited_content || digest.suggested_content;

// Check if content exists
if (!content) {
  throw new Error('No content found in digest');
}

// Clean content for LinkedIn posting
// Remove markdown bold syntax if any (**text** → text)
let cleanContent = content.replace(/\*\*(.*?)\*\*/g, '$1');

// Ensure proper line breaks
cleanContent = cleanContent.replace(/\n{3,}/g, '\n\n').trim();

// Return all data with clean_content added
return {
  json: {
    ...digest,
    clean_content: cleanContent
  }
};

// Parse AI JSON output and prepare dual content for Group + Feed
const MAX_LINKEDIN_CHARS = 3000;
const SAFE_LIMIT = 2800;

const aiOutput = $input.first().json;
let rawContent = aiOutput.message?.content || '';

// Clean up potential markdown code blocks
rawContent = rawContent
  .replace(/```json\n?/gi, '')
  .replace(/```\n?/gi, '')
  .trim();

// Parse JSON from AI output
let parsedContent;
try {
  parsedContent = JSON.parse(rawContent);
} catch (e) {
  // If JSON parsing fails, try to extract content manually
  console.log('JSON parse failed, attempting manual extraction');

  // Try to find JSON object in the response
  const jsonMatch = rawContent.match(/\{[\s\S]*\}/g);
  if (jsonMatch) {
    try {
      parsedContent = JSON.parse(jsonMatch[0]);
    } catch (e2) {
      // Fallback: use raw content as feed content
      parsedContent = {
        group_content: rawContent,
        group_first_comment: 'Links will be added manually.',
        feed_content: rawContent,
        hashtags: ['TechNews', 'Innovation', 'Technology']
      };
    }
  } else {
    parsedContent = {
      group_content: rawContent,
      group_first_comment: 'Links will be added manually.',
      feed_content: rawContent,
      hashtags: ['TechNews', 'Innovation', 'Technology']
    };
  }
}

// Extract and validate each content type
let groupContent = parsedContent.group_content || '';
let groupFirstComment = parsedContent.group_first_comment || '';
let feedContent = parsedContent.feed_content || '';
let hashtags = parsedContent.hashtags || ['TechNews'];

// Clean up content
const cleanContent = (content) => {
  return content
    .replace(/\n{3,}/g, '\n\n')
    .trim();
};

groupContent = cleanContent(groupContent);
feedContent = cleanContent(feedContent);

// Validate and truncate if needed
const truncateContent = (content, limit) => {
  if (content.length <= limit) return { content, truncated: false };

  // Find last paragraph break before limit
  const cutPoint = content.lastIndexOf('\n\n', limit - 100);
  if (cutPoint > limit - 500) {
    return { content: content.substring(0, cutPoint).trim(), truncated: true };
  }
  return { content: content.substring(0, limit - 50).trim() + '...', truncated: true };
};

const groupResult = truncateContent(groupContent, MAX_LINKEDIN_CHARS);
const feedResult = truncateContent(feedContent, SAFE_LIMIT);

// Add hashtags to feed content if not present
let finalFeedContent = feedResult.content;
if (!finalFeedContent.includes('#') && hashtags.length > 0) {
  finalFeedContent += '\n\n' + hashtags.map(t => `#${t.replace('#', '')}`).join(' ');
}

// Get week info from previous node
const weekInfo = $('Score & Select Top Articles').first().json;

return {
  group_content: groupResult.content,
  group_first_comment: groupFirstComment,
  feed_content: finalFeedContent,
  hashtags: hashtags,
  weekIdentifier: weekInfo.weekIdentifier,
  articleCount: weekInfo.articleCount,
  totalArticlesThisWeek: weekInfo.totalArticlesThisWeek,
  validation: {
    group_chars: groupResult.content.length,
    group_truncated: groupResult.truncated,
    feed_chars: finalFeedContent.length,
    feed_truncated: feedResult.truncated,
    status: (groupResult.truncated || feedResult.truncated) ? 'truncated' : 'valid'
  }
};
